    newRecord.setBorrowingDate(today);

    Date returnDue = new Date(today.getTime());
    returnDue.setTime(returnDue.getTime() + 7L * 24L * 60L * 60L * 1000L);
    newRecord.setReturnDue(returnDue);
    newRecord.setBook((Book) matchedDocument);

    getBorrowRecords().add(newRecord);
    return true;
    
